e close On: '=>'Распродажа завершится: ','Available On: '=>'Доступно: ','Sorry, no ticket available'=>'К сожалению, билетов нет','Ticket Selection --'=>'Выбор билетов --','Event Timelines'=>'Сроки проведения мероприятий','Location : '=>'Местоположение: ','Sorry, You Can not see this page, Because Its not your Attendee Information.'=>'К сожалению, вы не можете просмотреть эту страницу, поскольку это не ваша информация об участниках.','All Events Of '=>'Все события ','Event Schedule Details'=>'Подробности расписания мероприятий','When and where'=>'Когда и где','Docs'=>'Документы','Support'=>'Поддержка','Upgrade to PRO Version'=>'Обновите до PRO-версии','Carousel'=>'Карусель','Book'=>'Забронировать']];